const $=s=>document.querySelector(s);
const icons={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M19 5l-1 1M6 18l-1 1"/>',moon:'<path d="M20 15.5A9 9 0 0 1 8.5 4 9 9 0 1 0 20 15.5Z"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',back:'<path d="M20 12H5m6-6-6 6 6 6"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 16 5-4 4 4 4-5 5 5"/>',film:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 4v16M17 4v16M3 9h4m-4 6h4m10-6h4m-4 6h4"/>',layers:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',check:'<path d="m5 12 4 4L19 6"/>',folder:'<path d="M3 7V5h7l2 2h9v13H3V7Z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',plus:'<path d="M12 4v16M4 12h16"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.spark}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);let view=['home','director','workbench'].includes(params.get('view'))?params.get('view'):'director';let theme=params.get('theme')==='light'?'light':'dark';
const state={step:0,furthest:0,name:'白色精华瓶',brief:'为这款白色精华瓶制作一支 10 秒商品展示视频。自然光、干净克制，突出瓶身质感。',format:'9:16',boards:false,approved:[false,false],mode:'full',history:false,chat:'',scenes:['精华瓶置于浅色台面，柔和的侧光映出轮廓，镜头缓慢推近。','聚焦瓶身与瓶盖的细节，保持单瓶与原有标识，让光线缓缓掠过。'],chatDraft:'',workDuration:'5 秒',workType:'image',workPrompt:'白色精华瓶置于浅色台面，柔和自然光，保留瓶身、瓶盖和标签。',quality:'2K',count:'1',ratio:'1:1'};
const titles=['确认商品与方向','脚本与镜头计划','确认分镜画面','选择视频交付方式','你的作品，准备好了'];
const stageNames=['创作需求','脚本与镜头','分镜审核','视频生成','成片交付'];
function setTheme(){document.documentElement.dataset.theme=theme;$('#theme').innerHTML=icon(theme==='dark'?'sun':'moon');$('#theme').title=theme==='dark'?'切换浅色':'切换深色';}
$('#theme').onclick=()=>{theme=theme==='dark'?'light':'dark';setTheme();};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{capture();view=b.dataset.view;render();});
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
function capture(){if($('#product-name'))state.name=$('#product-name').value;if($('#brief'))state.brief=$('#brief').value;if($('#work-prompt'))state.workPrompt=$('#work-prompt').value;document.querySelectorAll('[data-scene]').forEach(el=>state.scenes[Number(el.dataset.scene)]=el.value);if($('#chat-input'))state.chatDraft=$('#chat-input').value;if($('#count'))state.count=$('#count').value;}
function go(step){capture();if(step<state.step){state.furthest=step;if(step<=2)state.approved=[false,false];if(step<2)state.boards=false;}state.step=step;state.furthest=Math.max(state.furthest,step);state.history=false;render();}
function dialog(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close());}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
function confirmQuote(kind,done){const image=kind==='image';dialog(`<div class="prototype-chip">报价弹窗演示 · 本次不会实际调用模型</div><h2>确认${image?'分镜画面':'视频'}生成</h2><p>${image?'2 张分镜图 · 2K':'2 个镜头 × 5 秒 · '+(state.mode==='full'?'生成后自动合成为一条视频':'分别交付镜头片段')}</p><div class="summary"><span>${image?'图片生成':'视频生成'} · 示例估算</span><b>${image?'¥0.24':'约 ¥0.88'}</b></div><p class="notice">正式产品会在这里展示服务端的当前报价。确认后才创建任务。</p><div class="modal-actions"><button class="btn" data-close>返回修改</button><button class="btn primary" id="quote-ok">确认并演示生成 ${icon('arrow')}</button></div>`);$('#quote-ok').onclick=()=>{$('#modal').close();done();};}
function home(){return `<section class="page"><div class="page-intro"><div class="eyebrow">YOUR CREATIVE SPACE</div><h1>今天，为商品拍点新东西。</h1><p class="muted">一个灵感，一张好图，或者一支完整的商品短片。</p></div><div class="entry-grid"><button class="entry primary-entry" id="new-project">${icon('spark')}<h2>和 AI 导演一起创作</h2><p>从一个想法开始，一步步确认脚本、画面与视频。</p><span class="plus">+</span></button><button class="entry" id="quick-entry">${icon('image')}<h2>直接进入工作台</h2><p>上传素材、套用模板，快速生成图片或单条视频。</p><span class="plus">↗</span></button></div><div class="section-heading"><h2>最近项目 <span class="muted" style="font-size:12px"> / 示例</span></h2><span class="muted" style="font-size:12px">继续你的创作</span></div><div class="projects">${['白色精华瓶 · 自然光','纯净白底商品图','精华瓶 · 质感特写'].map((n,i)=>`<button class="project" data-project="${i}"><img src="assets/scene-${i===2?2:1}.jpg" alt="白色瓶子示例"><div class="project-copy"><h3>${n}</h3><small>${['需求待确认','快捷工作台','分镜示例'][i]} · 今天</small></div></button>`).join('')}</div></section>`;}
function assistant(){const messages=['先从这件商品开始。<br>这次的<b>使用场景与画面方向</b>是什么？右侧已经整理好一个需求草稿，你可以直接修改。','我把这支短片拆成了两个镜头：<br><b>先看整体，再看细节。</b><br>请确认镜头数量和每一镜的表达。','脚本方向已确认。<br>接下来先看分镜画面，重点核对<b>商品外观、数量和构图</b>。确认后我们再做视频。','分镜已确认。<br>你可以一次生成全部镜头，并选择<b>自动合成成片</b>或<b>分别交付片段</b>。','这一轮创作已结束。<br>你可以看成片，也可以展开制作记录，回看每次确认的内容。'];return `<aside class="assistant"><div class="assistant-title"><span class="assistant-mark">${icon('spark')}</span><strong>AI 导演</strong><small>示例对话</small></div><div class="conversation"><small>你的创作想法</small><div class="user">${esc(state.brief)}</div><div class="tiny-material"><img src="assets/scene-1.jpg" alt="参考商品示例"><span style="font-size:11px">${esc(state.name)}<br><span class="muted">商品参考 · 示例</span></span></div><small>物料间 · 导演助手</small><div class="assistant-message">${messages[state.step]}</div><div class="hint-box">${state.step===0?'先把方向说清楚。模型和规格可以稍后调整。':'右侧确认只作用于当前步骤，后续生成会单独请你确认。'}</div>${state.chat?`<div class="user">${esc(state.chat)}</div><p class="notice">原型已记录这条演示输入；正式助手将在接入后处理。</p>`:''}</div><div class="chat-footer"><textarea id="chat-input" aria-label="给导演补充说明" placeholder="补充你的想法，或告诉我哪里需要调整…">${esc(state.chatDraft)}</textarea><div class="chat-actions"><span>仅用于本页交互演示</span><button id="send-chat" aria-label="发送演示消息">${icon('arrow')}</button></div></div></aside>`;}
function currentCard(){if(state.history)return historyCard();if(state.step===0)return `<div class="eyebrow">LET'S START WITH YOUR PRODUCT</div><h2>先认识这件商品。</h2><p class="subtitle">只要确认方向，接下来我们一起把它变成镜头。</p><div class="brief-grid"><div><label class="field-label" for="product-name">商品名称</label><input class="field" id="product-name" value="${esc(state.name)}"><label class="field-label" for="brief">这次想做什么？</label><textarea class="field area" id="brief">${esc(state.brief)}</textarea><label class="field-label">视频画幅</label><div class="option-row">${['9:16','16:9','1:1'].map(x=>`<button class="choice ${state.format===x?'selected':''}" data-format="${x}">${x}</button>`).join('')}</div></div><div class="product-asset"><img class="product-image" src="assets/scene-1.jpg" alt="白色精华瓶参考示例"><div><div class="asset-caption"><span>商品参考</span><span>示例素材</span></div><button class="btn small" id="replace-asset">${icon('image')} 更换参考图</button></div></div></div><div class="card-footer"><small>接下来：一起确定脚本与镜头</small><button class="btn primary" id="next">确认需求 ${icon('arrow')}</button></div>`;
if(state.step===1)return `<div class="eyebrow">STORY BEFORE CAMERA</div><h2>10 秒，让商品被看见。</h2><p class="subtitle">脚本草稿 · 2 个镜头 · 自然光与克制的镜头移动</p><div class="shot"><span class="shot-number">01</span><div style="flex:1"><strong>第一眼，完整呈现</strong><textarea class="field" aria-label="镜头一脚本" data-scene="0">${esc(state.scenes[0])}</textarea></div><span class="time">5 秒</span></div><div class="shot"><span class="shot-number">02</span><div style="flex:1"><strong>再靠近，看见质感</strong><textarea class="field" aria-label="镜头二脚本" data-scene="1">${esc(state.scenes[1])}</textarea></div><span class="time">5 秒</span></div><details class="settings"><summary>镜头设置</summary><p class="notice">当前原型用两镜示例展示流程。正式版按模型支持的原生时长选择，不裁剪或拉长。</p></details><div class="card-footer"><button class="btn text" id="back">${icon('back')} 修改需求</button><button class="btn primary" id="next">确认脚本与 2 个镜头 ${icon('arrow')}</button></div>`;
if(state.step===2)return `<div class="eyebrow">CHECK BEFORE MOTION</div><h2>先确认每一张画面。</h2><p class="subtitle">确认商品没有变，再让画面动起来。</p>${state.boards?`<div class="story-grid">${[1,2].map((i)=>`<article class="story"><img src="assets/scene-${i}.jpg" alt="镜头 ${i} 分镜示例"><div class="row spread"><small class="muted">镜头 0${i} · 5 秒</small><button class="btn text small" data-redo="${i}">重新生成</button></div><label><input type="checkbox" data-approve="${i-1}" ${state.approved[i-1]?'checked':''}>这张分镜符合我的商品</label></article>`).join('')}</div><p class="notice">请检查瓶身、标识、商品数量与画面。图中为已有验收素材示例。</p>`:`<div class="empty-story">${icon('image')}<span>脚本已确认，准备生成 2 张分镜</span><small>先查看报价，再确认生成</small></div>`}<div class="card-footer"><button class="btn text" id="back">${icon('back')} 修改脚本</button>${state.boards?`<button class="btn primary" id="next" ${!state.approved.every(Boolean)?'disabled':''}>确认全部分镜 ${icon('arrow')}</button>`:`<button class="btn primary" id="generate-boards">查看分镜报价 ${icon('arrow')}</button>`}</div>`;
if(state.step===3)return `<div class="eyebrow">MAKE IT MOVE</div><h2>这次，想怎么拿到视频？</h2><p class="subtitle">两种方式都会一键生成全部镜头，只需确认一次。</p><div class="mode-grid">${['full','clips'].map((m)=>`<button class="mode ${state.mode===m?'selected':''}" data-mode="${m}" aria-pressed="${state.mode===m}">${icon(m==='full'?'film':'layers')}<strong>${m==='full'?'直接合成一个视频':'生成各个镜头片段'}</strong><p>${m==='full'?'全部镜头完成后，按顺序自动拼接成片。':'分别拿到每个片段，也可以稍后再合成。'}</p></button>`).join('')}</div><div class="summary" style="margin-top:20px"><span>已确认镜头</span><b>2 镜 × 5 秒</b></div><div class="summary"><span>视频画幅</span><b>${esc(state.format)}</b></div><p class="notice">计划时长约 10 秒，实际成片时长以生成结果为准。</p><div class="card-footer"><button class="btn text" id="back">${icon('back')} 返回分镜</button><button class="btn primary" id="generate-video">查看整组报价 ${icon('arrow')}</button></div>`;
return `<div class="eyebrow">READY TO SHARE</div><h2>${state.mode==='full'?'你的第一支商品短片。':'每个镜头，都已就位。'}</h2><p class="subtitle">${state.mode==='full'?'示例成片 · 2 个镜头 · 实测 10.08 秒':'片段交付的交互示例 · 每个镜头可分别预览与下载'}</p>${state.mode==='full'?'<video class="video" src="assets/sample-film.mp4" poster="assets/scene-1.jpg" controls preload="metadata"></video>':`<div class="story-grid">${[1,2].map(i=>`<div class="story"><video style="width:100%;height:235px;background:#111;border-radius:8px" src="assets/clip-${i}.mp4" poster="assets/scene-${i}.jpg" controls preload="metadata"></video><p class="notice">镜头 0${i} · 示例片段 · 实测 5.04 秒</p><a class="btn small" href="assets/clip-${i}.mp4" download="物料间-示例镜头-${i}.mp4">下载这一镜</a></div>`).join('')}</div>`}<div class="card-footer"><button class="btn" id="history">${icon('layers')} 回看制作过程</button>${state.mode==='full'?`<a class="btn primary" href="assets/sample-film.mp4" download="物料间-示例成片.mp4">${icon('download')} 下载示例成片</a>`:'<span class="muted" style="font-size:12px">2 个独立片段</span>'}</div><div class="row" style="margin-top:16px"><button class="btn text small" id="save-template">保存为结构模板</button>${state.mode==='clips'?'<button class="btn text small" id="compose">演示合成成片</button>':''}</div>`;
}
function historyCard(){return `<div class="eyebrow">CREATIVE JOURNEY</div><h2>这件作品，如何诞生。</h2><p class="subtitle">已完成的制作记录。修改上游内容后，相关确认需要重新完成。</p><div class="history-list">${stageNames.map((n,i)=>`<article class="history-item"><span class="pill">0${i+1} · 已完成</span><h3 style="margin-top:18px">${n}</h3><p>${['商品与方向','2 镜 × 5 秒','2 张分镜已确认','整组生成','示例成片'][i]}</p>${i===2?'<img src="assets/scene-1.jpg" alt="分镜示例">':''}<button class="btn small" data-edit="${i}">回看</button></article>`).join('')}</div><button class="btn primary" id="return-film">返回交付 ${icon('arrow')}</button>`;}
function director(){return `<section class="director"><div class="project-bar"><div class="project-title"><span>${icon('folder')} ${esc(state.name)} · 自然光</span><small>本页演示项目</small></div><button class="btn small review" id="review" ${state.furthest<4?'disabled':''}>${icon('layers')} 制作记录</button></div><div class="director-body">${assistant()}<div class="stage-area"><div class="stage-heading"><span class="dot"></span><span>${state.history?'已完成 · 制作记录':stageNames[state.step]}</span><span class="step">${state.history?'REVIEW':`STEP 0${state.step+1}`}</span></div><section class="stage-card">${currentCard()}</section><div class="completed-trail">${Array.from({length:state.step},(_,i)=>`<button data-edit="${i}">✓ ${stageNames[i]} · 查看</button>`).join('')}</div></div></div></section>`;}
function workbench(){return `<section class="workbench"><div class="composer"><div class="row spread"><h2>快捷工作台</h2><span class="pill">直接创作</span></div><div class="option-row" style="margin-top:23px">${['image','video'].map(m=>`<button class="choice ${state.workType===m?'selected':''}" data-type="${m}">${icon(m==='image'?'image':'film')} ${m==='image'?'生成图片':'生成视频'}</button>`).join('')}</div><label class="field-label">商品参考</label><div class="tiny-material"><img src="assets/scene-1.jpg" alt="商品示例"><span class="muted" style="font-size:12px">白色精华瓶 · 示例素材</span></div><label class="field-label" for="work-prompt">画面描述</label><textarea id="work-prompt" class="field area" style="min-height:130px">${esc(state.workPrompt)}</textarea><button class="btn small" id="polish">${icon('spark')} 润色提示词</button><label class="field-label" style="margin-top:24px">画面比例</label><div class="option-row">${['1:1','9:16','16:9','3:4','4:3'].map(r=>`<button title="${r}" class="choice ratio ${state.ratio===r?'selected':''}" data-ratio="${r}" ${state.workType==='video'&&['3:4','4:3'].includes(r)?'disabled':''}><i></i>${r}</button>`).join('')}</div><label class="field-label">${state.workType==='image'?'清晰度':'时长 · 演示选项'}</label><div class="option-row">${(state.workType==='image'?['1K','2K']:['3 秒','5 秒','10 秒']).map((x,i)=>`<button class="choice ${state.workType==='image'?(state.quality===x?'selected':''):(state.workDuration===x?'selected':'')}" data-quality="${x}">${x}</button>`).join('')}</div><details class="settings"><summary>更多设置</summary><p class="notice">正式选项随当前模型能力变化。原型不代表支持更多型号与规格。</p><label>生成数量 <select class="field" id="count">${['1','2','4'].map(n=>`<option ${state.count===n?'selected':''}>${n}</option>`).join('')}</select></label></details><button class="btn primary" style="width:100%;margin-top:24px" id="quick-generate">查看报价并生成 ${icon('arrow')}</button><p class="notice">提示词润色按需使用，随时可以直接生成。</p></div><div class="result-panel"><div class="row spread"><h2>画面预览</h2><span class="pill">已有素材示例</span></div><div class="result-preview"><img src="assets/scene-1.jpg" alt="白色商品瓶子示例"><div class="result-meta"><span>白色精华瓶 · 自然光</span><span>示例预览</span></div></div><p class="notice">这里展示本项目已有样例，点击生成只演示确认与结果呈现。</p></div></section>`;}
function bind(){const on=(id,fn)=>{const el=$(id);if(el)el.onclick=fn;};on('#new-project',()=>{state.step=0;state.furthest=0;state.history=false;state.boards=false;state.approved=[false,false];state.chat='';state.chatDraft='';view='director';render();});on('#quick-entry',()=>{view='workbench';render();});document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{view=b.dataset.project==='1'?'workbench':'director';render();});on('#next',()=>{capture();if(state.step===0&&(!state.name.trim()||!state.brief.trim()))return toast('请先补充商品名称与创作方向。');if(state.step===2&&!state.approved.every(Boolean))return;go(state.step+1);});on('#back',()=>go(Math.max(0,state.step-1)));document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{capture();state.format=b.dataset.format;render();});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;render();});document.querySelectorAll('[data-approve]').forEach(b=>b.onchange=()=>{state.approved[Number(b.dataset.approve)]=b.checked;$('#next').disabled=!state.approved.every(Boolean);});on('#generate-boards',()=>confirmQuote('image',()=>{state.boards=true;render();}));document.querySelectorAll('[data-redo]').forEach(b=>b.onclick=()=>{dialog(`<h2>重新生成这一镜</h2><p>正式版会为选中的单镜重新报价。该原型仅演示重新审核，保留另一镜确认。</p><div class="modal-actions"><button class="btn" data-close>取消</button><button class="btn primary" id="redo-ok">演示重做并重新审核</button></div>`);$('#redo-ok').onclick=()=>{state.approved[Number(b.dataset.redo)-1]=false;$('#modal').close();render();};});on('#generate-video',()=>{if(!state.boards||!state.approved.every(Boolean))return toast('请先逐张确认分镜。');confirmQuote('video',()=>go(4));});on('#history',()=>{state.history=true;render();});on('#review',()=>{state.history=true;render();});on('#return-film',()=>{state.step=4;state.history=false;render();});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.edit);dialog(`<h2>回看${stageNames[i]}</h2><p>进入修改后，会保留历史素材，但本原型的下游确认将重置；重新生成仍需单独确认。</p><div class="modal-actions"><button class="btn" data-close>保留当前进度</button><button class="btn primary" id="edit-ok">进入查看与修改</button></div>`);$('#edit-ok').onclick=()=>{state.furthest=i;state.boards=i>=2;if(i<=2)state.approved=[false,false];$('#modal').close();go(i);};});on('#replace-asset',()=>{dialog(`<h2>更换商品参考</h2><p>在原型中选择一个示例即可。正式版会在这里提供素材选择与上传。</p><div class="story-grid"><img src="assets/scene-1.jpg" alt="商品示例一" style="width:100%;border-radius:12px"><img src="assets/scene-2.jpg" alt="商品示例二" style="width:100%;border-radius:12px"></div><div class="modal-actions"><button class="btn primary" data-close>使用当前示例</button></div>`);});on('#send-chat',()=>{const value=$('#chat-input').value.trim();if(!value)return;capture();state.chat=value;state.chatDraft='';render();});on('#save-template',()=>{dialog(`<h2>保存为结构模板</h2><p>复用镜头结构与节奏。下次套用时重新绑定商品素材。</p><label class="field-label" for="template-name">模板名称</label><input id="template-name" class="field" value="先整体，后细节 · 2 镜展示"><div class="modal-actions"><button class="btn" data-close>取消</button><button class="btn primary" id="template-ok">演示保存</button></div>`);$('#template-ok').onclick=()=>{if(!$('#template-name').value.trim())return;$('#modal').close();toast('模板保存交互已演示，未写入正式模板库。');};});on('#compose',()=>{dialog(`<h2>合成当前两个镜头</h2><p>按镜头 01 → 02 的顺序拼接已有片段，不重新生成。本原型只播放预置成片示例。</p><div class="modal-actions"><button class="btn" data-close>保留独立片段</button><button class="btn primary" id="compose-ok">确认并查看合成示例</button></div>`);$('#compose-ok').onclick=()=>{$('#modal').close();state.mode='full';render();};});document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{capture();state.workType=b.dataset.type;if(state.workType==='video'&&['3:4','4:3'].includes(state.ratio))state.ratio='9:16';render();});document.querySelectorAll('[data-ratio]').forEach(b=>b.onclick=()=>{capture();state.ratio=b.dataset.ratio;render();});document.querySelectorAll('[data-quality]').forEach(b=>b.onclick=()=>{capture();if(state.workType==='image')state.quality=b.dataset.quality;else state.workDuration=b.dataset.quality;b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');});on('#polish',()=>{capture();dialog(`<h2>润色你的画面描述</h2><p>润色结果示例，可编辑后再采用。不会自动生成图片或视频。</p><textarea id="polished" class="field area">${esc(state.workPrompt)} 镜头保持克制，画面留白，避免新增商品或改变原有标识。</textarea><div class="modal-actions"><button class="btn" data-close>保留原文</button><button class="btn primary" id="adopt">采用这版提示词</button></div>`);$('#adopt').onclick=()=>{state.workPrompt=$('#polished').value;$('#modal').close();render();};});on('#quick-generate',()=>{capture();dialog(`<div class="prototype-chip">快速生成确认示例</div><h2>确认本次生成</h2><p>${state.workType==='image'?'商品图片':'单条视频'} · ${esc(state.ratio)} · 当前规格仅作交互示例</p><p>正式费用将在接入当前模型报价后展示。</p><div class="modal-actions"><button class="btn" data-close>返回修改</button><button class="btn primary" id="quick-ok">确认并查看示例结果</button></div>`);$('#quick-ok').onclick=()=>{$('#modal').close();toast('已展示已有示例，未发起真实生成。');$('.result-panel').scrollIntoView({behavior:'smooth',block:'start'});};});}
function render(){document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});$('#app').innerHTML=view==='home'?home():view==='workbench'?workbench():director();bind();}
setTheme();render();
